import{B as e,Lt as t,Z as n,et as r,mt as i,nt as a,tt as o}from"./chunks/framework.CxxritPY.js";var s=JSON.parse(`{"title":"Decisions API","description":"OpenAI·Gemini의 빠른 의사결정 API가 실무에 필요한지 짚어봅니다.","frontmatter":{"title":"Decisions API","date":"2026-11-12T21:00+09:00","description":"OpenAI·Gemini의 빠른 의사결정 API가 실무에 필요한지 짚어봅니다.","tags":["Decisions API","OpenAI","Gemini","Jev"]},"headers":[],"relativePath":"posts/decisions-api.md","filePath":"posts/decisions-api.md","lastUpdated":1794620575000}`),c={name:`posts/decisions-api.md`},l={id:`frontmatter-title`,tabindex:`-1`};function u(e,s,c,u,d,f){return i(),r(`div`,null,[n(`h1`,l,[a(t(e.$frontmatter.title)+` `,1),s[0]||=n(`a`,{class:`header-anchor`,href:`#frontmatter-title`,"aria-label":`Permalink to “{{ $frontmatter.title }}”`},`​`,-1)]),s[1]||=o(`<p><a href="https://typesafe.ai" target="_blank" rel="noreferrer">TypeSafe AI</a>가 공개한 <a href="https://news.hada.io/topic?id=33751" target="_blank" rel="noreferrer">Jev</a>는 문장을 길게 생성하는 대신 정해진 선택지 중 답과 확률만 빠르게 돌려주는 모델이다. 이제는 Jev뿐만 아니라 OpenAI와 Google도 자체적인 빠른 의사결정을 위한 <strong>Decisions API</strong> 를 제공한다.</p><h2 id="openai-와-gemini" tabindex="-1">OpenAI 와 Gemini <a class="header-anchor" href="#openai-와-gemini" aria-label="Permalink to “OpenAI 와 Gemini”">​</a></h2><ul><li><strong>OpenAI</strong> — <code>gpt-6-luna</code> 기반의 <a href="https://developers.openai.com/api/docs/guides/decisions" target="_blank" rel="noreferrer">Decisions API</a> 정식 출시(GA) (2026.10.22)</li><li><strong>Gemini</strong> — <code>gemini-decision-1</code> 기반의 <a href="https://blog.google/innovation-and-ai/technology/developers-tools/gemini-decisions-api/" target="_blank" rel="noreferrer">Gemini Decisions API</a> 공개 (2026.11.11)</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">TypeSafe AI (Jev)</th><th style="text-align:left;">OpenAI Decisions API</th><th style="text-align:left;">Gemini Decisions API</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>기반 모델</strong></td><td style="text-align:left;"><code>jev-1.14.0</code></td><td style="text-align:left;"><code>gpt-6-luna</code></td><td style="text-align:left;"><code>gemini-decision-1</code></td></tr><tr><td style="text-align:left;"><strong>입력 형식</strong></td><td style="text-align:left;">텍스트, 이미지(실험)</td><td style="text-align:left;">텍스트, 이미지(base64)</td><td style="text-align:left;">텍스트, 이미지, 오디오, 영상, PDF</td></tr><tr><td style="text-align:left;"><strong>질문 유형</strong></td><td style="text-align:left;"><code>noul</code>, <code>choice</code>, <code>box</code> 등</td><td style="text-align:left;"><code>predicate</code>, <code>choice</code>, <code>score</code></td><td style="text-align:left;"><code>noul</code>, <code>choice</code>, <code>score</code></td></tr><tr><td style="text-align:left;"><strong>과금 방식</strong></td><td style="text-align:left;">요청·토큰 기반</td><td style="text-align:left;">입력 100만 토큰당 0.10달러</td><td style="text-align:left;">입력 100만 토큰당 0.10달러</td></tr></tbody></table><h2 id="웹-서비스에서-필요한가" tabindex="-1">웹 서비스에서 필요한가? <a class="header-anchor" href="#웹-서비스에서-필요한가" aria-label="Permalink to “웹 서비스에서 필요한가?”">​</a></h2><p><mark>일반적인 웹 서비스 기능으로 꼭 필요한지는 의문</mark> 이다. 고객 문의 분류나 우선순위 채점처럼 단순 판단만 필요한 경우는 드물고, 결국 요약·추출을 위해 Structured Outputs로 생성 모델을 다시 부르게 된다. 차라리 <code>PreToolUse</code> 검사나 <a href="/posts/codex-review">AI 문체 판별</a> 같은 <strong>AI 에이전트 훅의 가드레일 용도</strong> 로 Jev를 아직 잘 쓰고 있다.</p><p>하지만 OpenAI와 Gemini 모두 구독 플랜으로는 API를 지원하지 않아 별도 키 발급과 과금이 필요하므로, 이것마저도 별로라 따로 도입해 보진 않을 것 같다.</p>`,7)])}var d=e(c,[[`render`,u]]);export{s as __pageData,d as default};